PRAGMA foreign_keys=OFF;
CREATE TABLE IF NOT EXISTS "bookmark" (
	"bookmark_id"	INTEGER,
	"person"	INTEGER NOT NULL,
	"product"	INTEGER NOT NULL,
	PRIMARY KEY("bookmark_id"),
	UNIQUE("person", "product"),
	FOREIGN KEY("person") REFERENCES "person"("person_id") ON DELETE CASCADE,
	FOREIGN KEY("product") REFERENCES "product"("product_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "borrowing" (
	"borrowing_id"	INTEGER,
	"borrowing_comment"	TEXT,
	"person"	INTEGER NOT NULL,
	"borrower"	INTEGER NOT NULL,
	"storage"	INTEGER NOT NULL UNIQUE,
	PRIMARY KEY("borrowing_id"),
	FOREIGN KEY("borrower") REFERENCES "person"("person_id") ON DELETE CASCADE,
	FOREIGN KEY("person") REFERENCES "person"("person_id") ON DELETE CASCADE,
	FOREIGN KEY("storage") REFERENCES "storage"("storage_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "cas_number" (
	"cas_number_id"	INTEGER,
	"cas_number_label"	TEXT NOT NULL UNIQUE CHECK ("cas_number_label" <> ''),
	"cas_number_cmr"	TEXT,
	PRIMARY KEY("cas_number_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "ce_number" (
	"ce_number_id"	INTEGER,
	"ce_number_label"	TEXT NOT NULL UNIQUE CHECK ("ce_number_label" <> ''),
	PRIMARY KEY("ce_number_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "category" (
	"category_id"	INTEGER,
	"category_label"	TEXT NOT NULL UNIQUE CHECK ("category_label" <> ''),
	PRIMARY KEY("category_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "class_of_compound" (
	"class_of_compound_id"	INTEGER,
	"class_of_compound_label"	TEXT NOT NULL UNIQUE CHECK ("class_of_compound_label" <> ''),
	PRIMARY KEY("class_of_compound_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "empirical_formula" (
	"empirical_formula_id"	INTEGER,
	"empirical_formula_label"	TEXT NOT NULL UNIQUE CHECK ("empirical_formula_label" <> ''),
	PRIMARY KEY("empirical_formula_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "linear_formula" (
	"linear_formula_id"	INTEGER,
	"linear_formula_label"	TEXT NOT NULL UNIQUE CHECK ("linear_formula_label" <> ''),
	PRIMARY KEY("linear_formula_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "hazard_statement" (
	"hazard_statement_id"	INTEGER,
	"hazard_statement_label"	TEXT NOT NULL CHECK ("hazard_statement_label" <> ''),
	"hazard_statement_reference"	TEXT NOT NULL UNIQUE CHECK ("hazard_statement_reference" <> ''),
	"hazard_statement_cmr"	TEXT,
	PRIMARY KEY("hazard_statement_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "precautionary_statement" (
	"precautionary_statement_id"	INTEGER,
	"precautionary_statement_label"	TEXT NOT NULL CHECK ("precautionary_statement_label" <> ''),
	"precautionary_statement_reference"	TEXT NOT NULL UNIQUE CHECK ("precautionary_statement_reference" <> ''),
	PRIMARY KEY("precautionary_statement_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "physical_state" (
	"physical_state_id"	INTEGER,
	"physical_state_label"	TEXT NOT NULL UNIQUE CHECK ("physical_state_label" <> ''),
	PRIMARY KEY("physical_state_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "signal_word" (
	"signal_word_id"	INTEGER,
	"signal_word_label"	TEXT NOT NULL UNIQUE CHECK ("signal_word_label" <> ''),
	PRIMARY KEY("signal_word_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "symbol" (
	"symbol_id"	INTEGER,
	"symbol_label"	TEXT NOT NULL UNIQUE CHECK ("symbol_label" <> ''),
	PRIMARY KEY("symbol_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "tag" (
	"tag_id"	INTEGER,
	"tag_label"	TEXT NOT NULL UNIQUE CHECK ("tag_label" <> ''),
	PRIMARY KEY("tag_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "producer" (
	"producer_id"	INTEGER,
	"producer_label"	TEXT NOT NULL UNIQUE CHECK ("producer_label" <> ''),
	PRIMARY KEY("producer_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "producer_ref" (
	"producer_ref_id"	INTEGER,
	"producer_ref_label"	TEXT NOT NULL CHECK ("producer_ref_label" <> ''),
	"producer"	INTEGER NOT NULL,
	PRIMARY KEY("producer_ref_id"),
	UNIQUE("producer", "producer_ref_label"),
	FOREIGN KEY("producer") REFERENCES "producer"("producer_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "supplier" (
	"supplier_id"	INTEGER,
	"supplier_label"	TEXT NOT NULL UNIQUE CHECK ("supplier_label" <> ''),
	PRIMARY KEY("supplier_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "supplier_ref" (
	"supplier_ref_id"	INTEGER,
	"supplier_ref_label"	TEXT NOT NULL CHECK ("supplier_ref_label" <> ''),
	"supplier"	INTEGER NOT NULL,
	PRIMARY KEY("supplier_ref_id"),
	UNIQUE("supplier", "supplier_ref_label"),
	FOREIGN KEY("supplier") REFERENCES "supplier"("supplier_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "name" (
	"name_id"	INTEGER,
	"name_label"	TEXT NOT NULL UNIQUE CHECK ("name_label" <> ''),
	PRIMARY KEY("name_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "unit" (
	"unit_id"	INTEGER,
	"unit_label"	TEXT NOT NULL UNIQUE CHECK ("unit_label" <> ''),
	"unit_multiplier"	REAL NOT NULL DEFAULT 1 CHECK ("unit_multiplier" > 0),
	"unit_type"	TEXT NOT NULL CHECK ("unit_type" IN ('quantity', 'concentration', 'temperature', 'molecular_weight')),
	"unit"	INTEGER CHECK ("unit" <> "unit_id"),
	PRIMARY KEY("unit_id"),
	FOREIGN KEY("unit") REFERENCES "unit"("unit_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "permission" (
	"person"	INTEGER NOT NULL,
	"permission_name"	TEXT NOT NULL CHECK ("permission_name" IN ('n', 'r', 'w', 'b', 'all')),
	"permission_item"	TEXT NOT NULL CHECK ("permission_item" IN ('all', 'entities', 'products', 'rproducts', 'storages', 'store_locations')),
	"permission_entity"	INTEGER,
	FOREIGN KEY("person") REFERENCES "person"("person_id") ON DELETE CASCADE,
	FOREIGN KEY("permission_entity") REFERENCES "entity"("entity_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "entity" (
	"entity_id"	INTEGER,
	"entity_name"	TEXT NOT NULL UNIQUE CHECK ("entity_name" <> ''),
	"entity_description"	TEXT,
	PRIMARY KEY("entity_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "person" (
	"person_id"	INTEGER,
	"person_email"	TEXT NOT NULL UNIQUE CHECK ("person_email" <> ''),
	PRIMARY KEY("person_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "product" (
	"product_id"	INTEGER,
	"product_type"	TEXT NOT NULL CHECK ("product_type" IN ('chem', 'bio', 'cons')),
	"product_inchi"	TEXT,
	"product_inchikey"	TEXT,
	"product_canonical_smiles"	TEXT,
	"product_specificity"	TEXT,
	"product_msds"	TEXT,
	"product_restricted"	INTEGER NOT NULL DEFAULT 0 CHECK ("product_restricted" IN (0, 1)),
	"product_radioactive"	INTEGER NOT NULL DEFAULT 0 CHECK ("product_radioactive" IN (0, 1)),
	"product_threed_formula"	TEXT,
	"product_twod_formula"	TEXT,
	"product_disposal_comment"	TEXT,
	"product_remark"	TEXT,
	"product_qrcode"	TEXT,
	"product_sheet"	TEXT,
	"product_concentration"	REAL CHECK ("product_concentration" >= 0),
	"product_temperature"	REAL,
	"product_molecular_weight"	REAL CHECK ("product_molecular_weight" > 0),
	"cas_number"	INTEGER,
	"ce_number"	INTEGER,
	"person"	INTEGER NOT NULL DEFAULT 1,
	"empirical_formula"	INTEGER,
	"linear_formula"	INTEGER,
	"physical_state"	INTEGER,
	"signal_word"	INTEGER,
	"name"	INTEGER NOT NULL,
	"producer_ref"	INTEGER,
	"unit_molecular_weight"	INTEGER,
	"unit_temperature"	INTEGER,
	"category"	INTEGER,
	"product_number_per_carton"	INTEGER CHECK ("product_number_per_carton" > 0),
	"product_number_per_bag"	INTEGER CHECK ("product_number_per_bag" > 0),
	PRIMARY KEY("product_id"),
	FOREIGN KEY("cas_number") REFERENCES "cas_number"("cas_number_id"),
	FOREIGN KEY("category") REFERENCES "category"("category_id"),
	FOREIGN KEY("ce_number") REFERENCES "ce_number"("ce_number_id"),
	FOREIGN KEY("empirical_formula") REFERENCES "empirical_formula"("empirical_formula_id"),
	FOREIGN KEY("linear_formula") REFERENCES "linear_formula"("linear_formula_id"),
	FOREIGN KEY("name") REFERENCES "name"("name_id"),
	FOREIGN KEY("person") REFERENCES "person"("person_id") ON DELETE SET DEFAULT,
	FOREIGN KEY("physical_state") REFERENCES "physical_state"("physical_state_id"),
	FOREIGN KEY("producer_ref") REFERENCES "producer_ref"("producer_ref_id"),
	FOREIGN KEY("signal_word") REFERENCES "signal_word"("signal_word_id"),
	FOREIGN KEY("unit_molecular_weight") REFERENCES "unit"("unit_id"),
	FOREIGN KEY("unit_temperature") REFERENCES "unit"("unit_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "store_location" (
	"store_location_id"	INTEGER,
	"store_location_name"	TEXT NOT NULL CHECK ("store_location_name" <> ''),
	"store_location_color"	TEXT,
	"store_location_can_store"	INTEGER NOT NULL DEFAULT 0 CHECK ("store_location_can_store" IN (0, 1)),
	"store_location_full_path"	TEXT,
	"entity"	INTEGER NOT NULL,
	"store_location"	INTEGER CHECK ("store_location" <> "store_location_id"),
	PRIMARY KEY("store_location_id"),
	FOREIGN KEY("entity") REFERENCES "entity"("entity_id"),
	FOREIGN KEY("store_location") REFERENCES "store_location"("store_location_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "storage" (
	"storage_id"	INTEGER,
	"storage_creation_date"	INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
	"storage_modification_date"	INTEGER NOT NULL DEFAULT (strftime('%s', 'now')),
	"storage_entry_date"	INTEGER,
	"storage_exit_date"	INTEGER,
	"storage_opening_date"	INTEGER,
	"storage_expiration_date"	INTEGER,
	"storage_quantity"	REAL CHECK ("storage_quantity" >= 0),
	"storage_barecode"	TEXT,
	"storage_comment"	TEXT,
	"storage_reference"	TEXT,
	"storage_batch_number"	TEXT,
	"storage_to_destroy"	INTEGER NOT NULL DEFAULT 0 CHECK ("storage_to_destroy" IN (0, 1)),
	"storage_archive"	INTEGER NOT NULL DEFAULT 0 CHECK ("storage_archive" IN (0, 1)),
	"storage_qrcode"	BLOB,
	"storage_concentration"	REAL CHECK ("storage_concentration" >= 0),
	"storage_number_of_bag"	INTEGER CHECK ("storage_number_of_bag" > 0),
	"storage_number_of_carton"	INTEGER CHECK ("storage_number_of_carton" > 0),
	"person"	INTEGER NOT NULL DEFAULT 1,
	"product"	INTEGER NOT NULL,
	"store_location"	INTEGER NOT NULL,
	"unit_concentration"	INTEGER,
	"unit_quantity"	INTEGER,
	"supplier"	INTEGER,
	"storage"	INTEGER CHECK ("storage" <> "storage_id"),
	PRIMARY KEY("storage_id"),
	CHECK ("storage_exit_date" >= "storage_entry_date"),
	CHECK ("storage_expiration_date" >= "storage_entry_date"),
	CHECK ("storage_opening_date" >= "storage_entry_date"),
	FOREIGN KEY("person") REFERENCES "person"("person_id") ON DELETE SET DEFAULT,
	FOREIGN KEY("product") REFERENCES "product"("product_id"),
	FOREIGN KEY("storage") REFERENCES "storage"("storage_id") ON DELETE CASCADE,
	FOREIGN KEY("store_location") REFERENCES "store_location"("store_location_id"),
	FOREIGN KEY("supplier") REFERENCES "supplier"("supplier_id"),
	FOREIGN KEY("unit_concentration") REFERENCES "unit"("unit_id"),
	FOREIGN KEY("unit_quantity") REFERENCES "unit"("unit_id")
) STRICT;
CREATE TABLE IF NOT EXISTS "productclassesofcompounds" (
	"productclassesofcompounds_product_id"	INTEGER NOT NULL,
	"productclassesofcompounds_class_of_compound_id"	INTEGER NOT NULL,
	PRIMARY KEY("productclassesofcompounds_product_id","productclassesofcompounds_class_of_compound_id"),
	FOREIGN KEY("productclassesofcompounds_class_of_compound_id") REFERENCES "class_of_compound"("class_of_compound_id") ON DELETE CASCADE,
	FOREIGN KEY("productclassesofcompounds_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "producthazardstatements" (
	"producthazardstatements_product_id"	INTEGER NOT NULL,
	"producthazardstatements_hazard_statement_id"	INTEGER NOT NULL,
	PRIMARY KEY("producthazardstatements_product_id","producthazardstatements_hazard_statement_id"),
	FOREIGN KEY("producthazardstatements_hazard_statement_id") REFERENCES "hazard_statement"("hazard_statement_id") ON DELETE CASCADE,
	FOREIGN KEY("producthazardstatements_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "productprecautionarystatements" (
	"productprecautionarystatements_product_id"	INTEGER NOT NULL,
	"productprecautionarystatements_precautionary_statement_id"	INTEGER NOT NULL,
	PRIMARY KEY("productprecautionarystatements_product_id","productprecautionarystatements_precautionary_statement_id"),
	FOREIGN KEY("productprecautionarystatements_precautionary_statement_id") REFERENCES "precautionary_statement"("precautionary_statement_id") ON DELETE CASCADE,
	FOREIGN KEY("productprecautionarystatements_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "productsupplierrefs" (
	"productsupplierrefs_product_id"	INTEGER NOT NULL,
	"productsupplierrefs_supplier_ref_id"	INTEGER NOT NULL,
	PRIMARY KEY("productsupplierrefs_product_id","productsupplierrefs_supplier_ref_id"),
	FOREIGN KEY("productsupplierrefs_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE,
	FOREIGN KEY("productsupplierrefs_supplier_ref_id") REFERENCES "supplier_ref"("supplier_ref_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "productsymbols" (
	"productsymbols_product_id"	integer NOT NULL,
	"productsymbols_symbol_id"	integer NOT NULL,
	PRIMARY KEY("productsymbols_product_id","productsymbols_symbol_id"),
	FOREIGN KEY("productsymbols_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE,
	FOREIGN KEY("productsymbols_symbol_id") REFERENCES "symbol"("symbol_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "productsynonyms" (
	"productsynonyms_product_id"	integer NOT NULL,
	"productsynonyms_name_id"	integer NOT NULL,
	PRIMARY KEY("productsynonyms_product_id","productsynonyms_name_id"),
	FOREIGN KEY("productsynonyms_name_id") REFERENCES "name"("name_id") ON DELETE CASCADE,
	FOREIGN KEY("productsynonyms_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "producttags" (
	"producttags_product_id"	integer NOT NULL,
	"producttags_tag_id"	integer NOT NULL,
	PRIMARY KEY("producttags_product_id","producttags_tag_id"),
	FOREIGN KEY("producttags_product_id") REFERENCES "product"("product_id") ON DELETE CASCADE,
	FOREIGN KEY("producttags_tag_id") REFERENCES "tag"("tag_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "entitypeople" (
	"entitypeople_entity_id"	integer NOT NULL,
	"entitypeople_person_id"	integer NOT NULL,
	PRIMARY KEY("entitypeople_entity_id","entitypeople_person_id"),
	FOREIGN KEY("entitypeople_entity_id") REFERENCES "entity"("entity_id") ON DELETE CASCADE,
	FOREIGN KEY("entitypeople_person_id") REFERENCES "person"("person_id") ON DELETE CASCADE
) STRICT;
CREATE TABLE IF NOT EXISTS "personentities" (
	"personentities_person_id"	integer NOT NULL,
	"personentities_entity_id"	integer NOT NULL,
	PRIMARY KEY("personentities_person_id","personentities_entity_id"),
	FOREIGN KEY("personentities_entity_id") REFERENCES "entity"("entity_id"),
	FOREIGN KEY("personentities_person_id") REFERENCES "person"("person_id") ON DELETE CASCADE
) STRICT;
CREATE INDEX idx_borrowing ON borrowing (person, storage);
CREATE INDEX idx_product_cas_number ON product (cas_number);
CREATE INDEX idx_product_ce_number ON product (ce_number);
CREATE INDEX idx_product_empirical_formula ON product (empirical_formula);
CREATE INDEX idx_product_linear_formula ON product (linear_formula);
CREATE INDEX idx_product_name ON product (name);
CREATE INDEX idx_product_type ON product (product_type);
CREATE INDEX idx_product_person ON product (person);
CREATE INDEX idx_product_category ON product (category);
CREATE INDEX idx_product_producer_ref ON product (producer_ref);
CREATE INDEX idx_product_signal_word ON product (signal_word);
CREATE INDEX idx_product_unit_temperature ON product (unit_temperature);
CREATE INDEX idx_product_unit_molecular_weight ON product (unit_molecular_weight);
CREATE INDEX idx_producttags_tag_reverse ON producttags (producttags_tag_id, producttags_product_id);
CREATE INDEX idx_productsynonyms_name_reverse ON productsynonyms (productsynonyms_name_id, productsynonyms_product_id);
CREATE INDEX idx_productsymbols_symbol_reverse ON productsymbols (productsymbols_symbol_id, productsymbols_product_id);
CREATE INDEX idx_productsupplierrefs_supplier_ref_reverse ON productsupplierrefs (productsupplierrefs_supplier_ref_id, productsupplierrefs_product_id);
CREATE INDEX idx_producthazardstatements_hazard ON producthazardstatements (producthazardstatements_hazard_statement_id, producthazardstatements_product_id);
CREATE INDEX idx_productprecautionarystatements_precautionary ON productprecautionarystatements (productprecautionarystatements_precautionary_statement_id, productprecautionarystatements_product_id);
CREATE INDEX idx_productclassesofcompounds_coc ON productclassesofcompounds (productclassesofcompounds_class_of_compound_id, productclassesofcompounds_product_id);
CREATE UNIQUE INDEX idx_permission_unique ON permission (person, permission_name, permission_item, IFNULL(permission_entity, -1));
CREATE INDEX idx_permission_fast ON permission (person, permission_item, permission_name);
CREATE INDEX idx_permission_item ON permission (permission_item);
CREATE INDEX idx_permission_name ON permission (permission_name);
CREATE INDEX idx_permission_entity ON permission (permission_entity);
CREATE INDEX idx_store_location_name ON store_location (store_location_name);
CREATE INDEX idx_store_location_entity ON store_location (entity);
CREATE INDEX idx_store_location_parent ON store_location (store_location);
CREATE INDEX idx_entitypeople_person ON entitypeople (entitypeople_person_id);
CREATE INDEX idx_personentities_entity ON personentities (personentities_entity_id);
CREATE INDEX idx_storage ON storage (product);
CREATE INDEX idx_storage_store_location ON storage (store_location);
CREATE INDEX idx_storage_person ON storage (person);
CREATE INDEX idx_storage_supplier ON storage (supplier);
CREATE INDEX idx_storage_storage ON storage (storage);
